<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';
use App\Core\Database;use App\Services\RandomPairingService;use App\Services\LiveDisplaySessionService;
$p=Database::connection();$token=trim((string)($_GET['token']??$_POST['token']??''));$link=RandomPairingService::byToken($p,$token);if(!$link){http_response_code(403);exit('This Emcee Match Link is invalid, expired, confirmed or revoked.');}$round=(int)$link['round_id'];$test=$link['data_mode']==='test';$pre=$test?'bdc_test_':'bdc_';$q=$p->prepare("SELECT r.*,e.name event_name FROM {$pre}scoring_rounds r JOIN {$pre}events e ON e.id=r.event_id WHERE r.id=:r");$q->execute(['r'=>$round]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Final round not found.');}$notice='';$error='';$result=null;$autoReveal=false;
if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=(string)($_POST['action']??'');if($action==='randomize'){$result=RandomPairingService::randomize($p,$round,$test,null);$s=LiveDisplaySessionService::forEvent($p,(int)$r['event_id'],$test);if(!$s)throw new RuntimeException('Ask the administrator to generate the Live Display link first.');LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'drumroll',0);$autoReveal=true;$notice='Random match secured. Drum roll started; pairings reveal automatically in 30 seconds.';}elseif($action==='reveal'){LiveDisplaySessionService::update($p,(int)$r['event_id'],$test,['round_id'=>$round,'screen_type'=>'matching'],0);LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'none',0);$notice='Pairings revealed on the event projector.';}elseif($action==='fireworks'){LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'fireworks',0);$notice='Fireworks sent to projection.';}elseif($action==='confetti'){LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'confetti',0);$notice='Confetti sent to projection.';}elseif($action==='clear'){LiveDisplaySessionService::effect($p,(int)$r['event_id'],$test,'none',0);$notice='Projection effect cleared.';}}catch(Throwable $e){$error=$e->getMessage();}}
if($autoReveal){LiveDisplaySessionService::update($p,(int)$r['event_id'],$test,['round_id'=>$round,'screen_type'=>'holding'],0);}
$pairs=$p->prepare("SELECT fp.pair_number,fp.pairing_status,l.bib_number leader_bib,l.display_name leader_name,f.bib_number follower_bib,f.display_name follower_name FROM {$pre}scoring_final_pairs fp JOIN {$pre}scoring_entries l ON l.id=fp.leader_entry_id LEFT JOIN {$pre}scoring_entries f ON f.id=fp.follower_entry_id WHERE fp.round_id=:r ORDER BY fp.pair_number");$pairs->execute(['r'=>$round]);$pairs=$pairs->fetchAll();
if($autoReveal):?><form id="autoReveal" method="post" style="display:none"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="action" value="reveal"></form><script>let seconds=30;addEventListener('DOMContentLoaded',()=>{const box=document.createElement('div');box.className='alert alert-warning fw-bold';box.innerHTML='🎵 Drum roll · Pairings reveal in <span id="revealCountdown">30</span> seconds';document.querySelector('main').prepend(box);const start=document.querySelector('button[value="randomize"]');if(start){start.disabled=true;start.textContent='Reveal in progress…';}});const revealTimer=setInterval(()=>{seconds--;const el=document.getElementById('revealCountdown');if(el)el.textContent=String(seconds);if(seconds<=0){clearInterval(revealTimer);document.getElementById('autoReveal').submit();}},1000);</script><?php endif;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Emcee Random Match</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#0b1220;color:#fff}.card{color:#172033}.match{font-size:1.05rem}</style></head><body><main class="container py-4" style="max-width:900px"><div class="text-warning fw-bold"><?=$test?'TESTING · ':''?>EMCEE PRESENTATION</div><h1>Random Final Match</h1><p><?=e($r['event_name'])?> · <?=e(ucwords(str_replace('_',' ',$r['division'])))?></p><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card mb-3"><div class="card-body"><form method="post" onsubmit="return confirm('Generate a new secure random draft match and show it on projection?');"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-warning btn-lg w-100" name="action" value="randomize">🎲 Start Random Match</button></form><div class="d-flex gap-2 mt-3"><form method="post" class="flex-fill"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-danger w-100" name="action" value="fireworks">🎆 Fireworks</button></form><form method="post" class="flex-fill"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-primary w-100" name="action" value="confetti">🎉 Confetti</button></form><form method="post"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-outline-secondary" name="action" value="clear">Clear</button></form></div><div class="small text-muted mt-3">Algorithm: Secure Fisher–Yates using PHP random_int(). Pairing remains Draft until Chief Judge/Admin confirms it.</div></div></div><div class="card"><div class="card-body"><h2 class="h5">Current Draft Matches</h2><?php if(!$pairs):?><p class="text-muted">Press Start Random Match.</p><?php else:foreach($pairs as $x):?><div class="match border-bottom py-2"><strong>Couple <?=$x['pair_number']?></strong> · Bib <?=$x['leader_bib']?> <?=e($x['leader_name'])?> + Bib <?=$x['follower_bib']?> <?=e($x['follower_name'])?></div><?php endforeach;endif;?></div></div></main></body></html>
